	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "incident_title_chk" CHECK (btrim(title) <> ''),
	CONSTRAINT "incident_severity_chk" CHECK (severity in ('degraded', 'down')),
	CONSTRAINT "incident_state_chk" CHECK (state in ('investigating', 'identified', 'monitoring', 'resolved')),
